40	        }
41	        String soundex = OwnerIdentity.soundex(owner.getLastName());
42	        String identityKey = OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
43	        Owner match = null;
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (Boolean.TRUE.equals(existing.getDeleted())) {
46	                continue; // a soft-deleted owner is not a duplicate to flag against
47	            }
48	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
49	                continue; // never match the new owner against itself
50	            }
51	            if (!postcode.equals(existing.getPostcode())
52	                    || !soundex.equals(OwnerIdentity.soundex(existing.getLastName()))) {
