5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
10	
11	/**
12	 * Step of {@code POST /api/owners}: rejects the request 429 once 100 or more owners already carry
13	 * this request's effective registration date. That date is the one supplied in the request, or the
14	 * server date when none was supplied, rolled forward to the next business day (see
15	 * {@link ApplyRegistrationDate}), so this caps the number of owners registered on a single business
16	 * day. Runs before {@link BuildOwner} so no owner is persisted on rejection.
17	 */
18	public class RequireDailyCapacity {
19	
20	    /** Maximum number of owners permitted to register on a single day. */
21	    private static final int DAILY_LIMIT = 100;
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DailyLimitExceededException {
25	        LocalDate registrationDate = RegistrationDate.effective(request.getRegistrationDate());
26	        long count = 0;
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (registrationDate.equals(existing.getRegistrationDate())) {
29	                count++;
30	            }
31	        }
32	        if (count >= DAILY_LIMIT) {
33	            throw new DailyLimitExceededException();
34	        }
35	    }
36	}
